mapper.select:
SELECT GOODS_CD, GOODS_NM, SALE_PRC, STOCK_QTY, SALE_STAT
  FROM TB_GOODS
 WHERE GOODS_CD = #{goodsCd}

SELECT CPN_NO, MBR_NO, DC_AMT, USE_YN
  FROM TB_COUPON
 WHERE CPN_NO = #{cpnNo}

mapper.update:
UPDATE TB_NEW_ORD_APPLY
   SET APPLY_STAT = 'R', UPD_DT = #{now}
 WHERE ORD_NO = #{ordNo} AND APPLY_STAT = 'A'

UPDATE TB_GOODS
   SET STOCK_QTY = STOCK_QTY - #{qty}
 WHERE GOODS_CD = #{goodsCd}
   AND SALE_STAT = '01'
   AND STOCK_QTY >= #{qty}
   AND SALE_PRC = #{expectedPrice}

UPDATE TB_COUPON
   SET USE_YN = 'Y', USE_ORD_NO = #{ordNo}
 WHERE CPN_NO = #{cpnNo} AND MBR_NO = #{mbrNo} AND USE_YN = 'N'

UPDATE TB_COUPON
   SET USE_YN = 'N', USE_ORD_NO = NULL
 WHERE CPN_NO = #{cpnNo} AND USE_YN = 'Y' AND USE_ORD_NO = #{ordNo}

UPDATE TB_MEMBER
   SET POINT_AMT = POINT_AMT - #{amount}
 WHERE MBR_NO = #{mbrNo} AND POINT_AMT >= #{amount}
